// Temporary analysis only. No production dependencies, no saved game changes.
// The policy functions receive visible tiles/counts only; wall access is confined
// to simulateOnline's draw closure. No kongs or wild-card transformations.
export const POLICY_VERSION = 'visible-blocks-v2';
const isTerminal = x => x >= 27 || x % 9 === 0 || x % 9 === 8;
const suit = x => x < 27 ? Math.floor(x / 9) : 3;
const countsOf = tiles => { const c=Array(34).fill(0); for(const t of tiles)c[typeof t==='number'?t:t.face]++; return c; };
const completeGroups = c => {
  const out=[];
  for(let f=0;f<34;f++)if(c[f]>=3)out.push([f,f,f]);
  for(let s=0;s<3;s++)for(let r=0;r<7;r++){const f=s*9+r;if(c[f]&&c[f+1]&&c[f+2])out.push([f,f+1,f+2]);}
  return out;
};
const groupKind = a => a.every(x=>x===a[0])?'pung':'chow';
function mainSuitOf(c){let best=0,value=-Infinity;for(let s=0;s<3;s++){let q=0;for(let r=0;r<9;r++)q+=c[s*9+r]*3+(c[s*9+r]>=2?1:0);if(q>value){best=s;value=q;}}return best;}
function retainOpening(hand,route,mainSuit,strategy){
  const c=countsOf(hand),meldFaces=new Set(completeGroups(c).flat()), ranked=hand.map((t,i)=>{const f=t.face,st=suit(f),r=f%9;let score=0;
    if(strategy==='wins-first'){
      if(meldFaces.has(f))score=70;
      else if(c[f]>=2)score=40;
      else if(st<3)for(let d of [-2,-1,1,2])if(r+d>=0&&r+d<9&&c[f+d])score=Math.max(score,Math.abs(d)===1?25:20);
      if(score>0){if(route==='high'&&st===mainSuit)score+=3;if(route==='pungs'&&c[f]>=2)score+=3;if(route==='growth'&&st<3)score+=2;}
      return {id:t.id,face:f,score,i};
    }
    if(route==='high')score=st===mainSuit?100+c[f]*2:-100;
    else if(route==='pungs')score=c[f]>=2?40+c[f]*10:-100;
    else {
      if(st<3){score=c[f]>=2?20:0;for(let d of [-2,-1,1,2])if(r+d>=0&&r+d<9&&c[f+d])score+=Math.abs(d)===1?13:8;}
      else score=c[f]>=2?18:-30;
      if(route==='held'&&isTerminal(f))score+=9;
    }
    return {id:t.id,face:f,score,i};
  }).sort((a,b)=>b.score-a.score||a.i-b.i);
  const cap=strategy==='wins-first'?12:route==='high'?12:route==='pungs'?10:8;
  const keep=new Set(ranked.filter(x=>x.score>0).slice(0,cap).map(x=>x.id));
