  for(let i=0;i<12;i++)draw();
  const initial=hand.map(t=>t.face),mainSuit=mainSuitOf(countsOf(hand));
  const redrawIds=retainOpening(hand,route,mainSuit,strategy),drop=new Set(redrawIds);
  for(let i=hand.length-1;i>=0;i--)if(drop.has(hand[i].id))discard.push(...hand.splice(i,1));
  for(let i=0;i<redrawIds.length;i++)draw();
  const afterRedraw=hand.map(t=>t.face);
  const edit=improveOpening(hand,route,mainSuit,relics,inkBudget,strategy);
  const startCounts=countsOf(hand),pairCount=startCounts.reduce((n,c)=>n+(mode==='mcr'?Math.floor(c/2):Number(c>=2)),0);
