  const blocks=[];let forcedCommits=0,actionCount=0;
  while(formed.length<14){
    const action=pairMode?choosePairAction(hand,blocks,mode,route):chooseNormalAction(hand,blocks,route,mainSuit,seenCounts,strategy);
    if(!action){
      // No legal extension of this greedy block plan. Still finish 14 tiles;
      // the real engine, not this plan, decides whether another decomposition wins.
      let ti=0;for(let i=1;i<hand.length;i++)if(route==='held'&&isTerminal(hand[ti].face)&&!isTerminal(hand[i].face))ti=i;
